package com.careerpilot.modules.scheduling.entity;import com.careerpilot.modules.assessment.entity.*;import com.careerpilot.modules.auth.entity.User;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.*;@Entity @Table(name="scheduled_exams")@Getter@Setter@NoArgsConstructor public class ScheduledExam{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="assessment_id")private Assessment assessment;@Column(nullable=false,length=180)private String title;@Column(length=2000)private String instructions;@Column(name="scheduled_start",nullable=false)private Instant scheduledStart;@Column(name="scheduled_end",nullable=false)private Instant scheduledEnd;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ScheduledExamStatus status;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="created_by_user_id")private User createdBy;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="owner_user_id")private User owner;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="attempt_id",unique=true)private AssessmentAttempt attempt;@Column(name="reschedule_count",nullable=false)private int rescheduleCount;@Column(name="last_rescheduled_at")private Instant lastRescheduledAt;@Column(name="cancelled_at")private Instant cancelledAt;@Column(name="reminder_sent_at")private Instant reminderSentAt;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@OneToMany(mappedBy="scheduledExam",cascade=CascadeType.ALL,orphanRemoval=true)private List<ScheduledExamCandidate>candidates=new ArrayList<>();@PrePersist void create(){if(id==null)id=UUID.randomUUID();Instant n=Instant.now();if(createdAt==null)createdAt=n;updatedAt=n;if(status==null)status=ScheduledExamStatus.SCHEDULED;}@PreUpdate void update(){updatedAt=Instant.now();}}
